SELECT t.rec_id AS record_id,t."供应商" AS "供应商",t."审核依据" AS "审核依据",(t."审核状态").name AS "审核状态",t."操作人" AS "操作人",t."更新时间" AS "更新时间",t."有效期" AS "有效期",t."维护负责人" AS "维护负责人",t."证照编号" AS "证照编号",t."资质名称" AS "资质名称",(t."资质类型").name AS "资质类型",t."资质附件" AS "资质附件",t."长期有效" AS "长期有效",s.rec_id AS supplier_id,s."供应商名称" AS supplier_name,s."国家" AS supplier_country,(s."推广阶段").name AS supplier_stage FROM "SupplierQualifications" AS t LEFT JOIN "Suppliers" AS s ON t."供应商" @> ARRAY[s.rec_id] INNER JOIN "Members" AS access_member ON (access_member."用户").id = CURRENT_USER_ID() LEFT JOIN "Roles" AS access_role ON access_member."角色编码" = access_role."角色编码" WHERE (access_member."状态").name = '启用' AND ((access_member."角色编码" IS NULL AND (access_member."角色").name IN ('管理员','采购','中央仓','技术','只读')) OR (access_role."启用" = TRUE AND access_role."权限代码" LIKE '%|qualification.read|%')) ORDER BY t.rec_id ASC LIMIT 500 OFFSET $1